class Solution {
public:
    long long numberOfSubstrings(string s, int k) {
        vector<int> freq(26, 0);
        long long ans = 0;
        int left = 0, valid = 0;
        for (int right = 0; right < static_cast<int>(s.size()); ++right) {
            if (++freq[s[right] - 'a'] == k) ++valid;
            while (valid > 0) {
                if (freq[s[left] - 'a']-- == k) --valid;
                ++left;
            }
            ans += left;
        }
        return ans;
    }
};
